head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataMap > firstSetSubmission]<br/>Submission 모듈로 Key 에 값(Value)을 설정했을때 원본값(Origin Value)을 재설정할지 설정합니다.",
    "validation" : [
        "미설정 또는 false 설정 시 Submission 모듈로 Key 에 값(Value)이 설정되어도 원본값(Origin Value)을 재설정 하지 않습니다.",
        "true 설정 시 Submission 모듈로 Key 에 값(Value)이 설정되면 전체 Key 의 원본값(Origin Value)이 재설정됩니다.",
        "true 설정 시 전체 Key 의 '변경여부' 상태값도 false('변경없음')로 재설정됩니다." 
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {      
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof input1 !== 'undefined') {
        input1.remove();
    }  

    // 조건 설정       
    let properties = {
        firstSetSubmission: con_firstSetSubmission.getText(),
    };

    let cList = $c.gcm.createCList(properties);  

    // target 생성
    $c.gcm.createBasicDataMap(cList);

    // input 생성
    $c.gcm.createEmptyInput('ref="data:target1.key1" style="width:200px;"', '', 'input1');  

    // scwin.btn_getOriginal_onclick();
}   



scwin.btn_smReq_onclick = function (e) {
    $p.executeSubmission("sm_getData");
};



scwin.sm_getData_submitdone = function (e) {
    scwin.btn_getOriginal_onclick();
}



scwin.btn_getModifiedJSON_onclick = function (e) {
    let rtn = target1.getModifiedJSON();
    let jsonString = JSON.stringify(rtn);

    wf_body_bottom.getObj("scwin").setReturnValue("getModifiedJSON : " + jsonString);  
}



scwin.btn_getOriginal_onclick = function (e) {    
    let rtn = "";

    rtn = target1.getOriginal("key1");
    wf_body_bottom.getObj("scwin").setReturnValue("getOriginal : " + rtn);  

    scwin.btn_getModifiedJSON_onclick();
};
